/**
 * Generates a fresh untradeable 80 OVR Welcome starter squad for first-time players:
 * - ST is always IShowSpeed (80 OVR, Club: International, League: International)
 * - Every other position in 4-3-3 Attack + 7 bench slots is randomly drawn by position
 * - Plus 5 additional random 80 OVR starter substitute/reserve players in club inventory
 */
export function generateRandomWelcomeSquad(): {
  starterIds: string[];
  benchIds: string[];
  reserveIds: string[];
  ownedPlayerIds: string[];
} {
  const used = new Set<string>(['welcome_st_ishowspeed_80']);
  const lwPool = ['welcome_lw_1', 'welcome_lw_2', 'welcome_lw_3'];
  const rwPool = ['welcome_rw_1', 'welcome_rw_2', 'welcome_rw_3', 'welcome_rw_4'];
  const camPool = ['welcome_cam_1', 'welcome_cam_2', 'welcome_cam_3', 'welcome_cam_4'];
  const cmPool = [
    'welcome_cm_1',
    'welcome_cm_2',
    'welcome_cm_3',
    'welcome_cm_4',
    'welcome_cm_5',
  ];
  const cdmPool = ['welcome_cdm_1', 'welcome_cdm_2', 'welcome_cdm_3'];
  const lbPool = ['welcome_lb_1', 'welcome_lb_2', 'welcome_lb_3'];
  const cbPool = [
    'welcome_cb_1',
    'welcome_cb_2',
    'welcome_cb_3',
    'welcome_cb_4',
    'welcome_cb_5',
  ];
  const rbPool = ['welcome_rb_1', 'welcome_rb_2', 'welcome_rb_3', 'welcome_rb_4'];
  const gkPool = ['welcome_gk_1', 'welcome_gk_2', 'welcome_gk_3'];

  const [lw] = pickDistinctRandomIds(lwPool, 1, used);
  const [rw] = pickDistinctRandomIds(rwPool, 1, used);
  const [cam] = pickDistinctRandomIds(camPool, 1, used);
  const [cm1, cm2] = pickDistinctRandomIds(cmPool, 2, used);
  const [lb] = pickDistinctRandomIds(lbPool, 1, used);
  const [cb1, cb2] = pickDistinctRandomIds(cbPool, 2, used);
  const [rb] = pickDistinctRandomIds(rbPool, 1, used);
  const [gk] = pickDistinctRandomIds(gkPool, 1, used);

  const starterIds = [
    lw,
    'welcome_st_ishowspeed_80',
    rw,
    cam,
    cm1,
    cm2,
    lb,
    cb1,
    cb2,
    rb,
    gk,
  ];

  const benchIds = [
    ...pickDistinctRandomIds(gkPool, 1, used),
    ...pickDistinctRandomIds(camPool, 1, used),
    ...pickDistinctRandomIds([...lwPool, ...rwPool], 1, used),
    ...pickDistinctRandomIds(cdmPool, 1, used),
    ...pickDistinctRandomIds(cmPool, 1, used),
    ...pickDistinctRandomIds(cbPool, 1, used),
    ...pickDistinctRandomIds([...rbPool, ...lbPool], 1, used),
  ];

  // Thêm 5 cầu thủ tân thủ random dự bị vào kho CLB
  const reserveIds = pickDistinctRandomIds(ALL_WELCOME_RANDOM_POOL_IDS, 5, used);

  return {
    starterIds,
    benchIds,
    reserveIds,
    ownedPlayerIds: [...starterIds, ...benchIds, ...reserveIds],
  };
}

