const WELCOME_MISSING_AVATAR =
  '/assets/aistudio/_nh_c_u_th__n_u_kh_ng_hi_n_th_____c_e141ec44.png';

function createWelcomePositionPlayer(
  id: string,
  name: string,
  position: PlayerCard['position'],
  club: string,
  league: string,
  nation: string,
  nationFlag: string,
  stats: [number, number, number, number, number, number],
  eaPlayerId: number,
  foot: 'Trái' | 'Phải' = 'Phải'
): PlayerCard {
  const [pac, sho, pas, dri, def, phy] = stats;
  return {
    id,
    name,
    fullName: `${name} (Welcome · Không Giao Dịch)`,
    ovr: 80,
    position,
    club,
    nation,
    nationFlag,
    league,
    cardType: 'WELCOME',
    pac,
    sho,
    pas,
    dri,
    def,
    phy,
    avatarUrl: `https://cdn.futbin.com/content/fifa25/img/players/${eaPlayerId}.png`,
    avatarFallbackUrl: WELCOME_MISSING_AVATAR,
    skillMoves: position === 'GK' ? 1 : 3,
    weakFoot: 3,
    foot,
    workRate: 'Trung bình/Trung bình',
    height: position === 'GK' || position === 'CB' ? '188 cm' : '180 cm',
    priceEstimate: 'Không Giao Dịch',
    isExchangeExclusive: true,
    isUntradeableOnly: true,
    isTradeable: false,
  };
}

